ALTER TABLE users ADD COLUMN IF NOT EXISTS tenant_id TEXT NOT NULL DEFAULT 'default';
CREATE TABLE IF NOT EXISTS regulated_matters(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,external_reference TEXT NOT NULL,matter_type TEXT NOT NULL,idempotency_key TEXT NOT NULL,consent_receipt_id TEXT,state TEXT NOT NULL DEFAULT 'intake',created_by BIGINT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(tenant_id,idempotency_key),CHECK(state IN('intake','active','professional_review','decided','appealed','declined','withdrawn','reopened','closed')));
CREATE TABLE IF NOT EXISTS matter_evidence(id BIGSERIAL PRIMARY KEY,matter_id BIGINT NOT NULL REFERENCES regulated_matters(id) ON DELETE RESTRICT,sha256 CHAR(64) NOT NULL,source TEXT NOT NULL,document_version INTEGER NOT NULL,privilege_level TEXT NOT NULL,metadata JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(matter_id,sha256,document_version));
CREATE TABLE IF NOT EXISTS matter_deadlines(id BIGSERIAL PRIMARY KEY,matter_id BIGINT NOT NULL REFERENCES regulated_matters(id) ON DELETE RESTRICT,rule_citation TEXT NOT NULL,due_at TIMESTAMPTZ NOT NULL,calculation_inputs JSONB NOT NULL,status TEXT NOT NULL,created_by BIGINT NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW(),CHECK(status IN('open','satisfied','superseded')));
CREATE TABLE IF NOT EXISTS matter_events(id BIGSERIAL PRIMARY KEY,matter_id BIGINT NOT NULL REFERENCES regulated_matters(id) ON DELETE RESTRICT,actor_id BIGINT NOT NULL,from_state TEXT,to_state TEXT NOT NULL,citations JSONB NOT NULL DEFAULT '[]',reason TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS regulated_matters_tenant_state_idx ON regulated_matters(tenant_id,state);
